    @check_rat
    def verify_bts_status(self, **kwargs):
        """ This function verifies bts is on air or not, considering status of all available RAT
            cells
            :param req_rat: which RATs status to be checked.
            :param should_be_onair: BTS should be on air or not
            :param wait_for: Time to wait(seconds) before checking for status
            :param alias: Name of execution context
        """
        # time.sleep(float(wait_for))
        req_rat = kwargs.pop("req_rat", 'all')
        should_be_onair = kwargs.pop('should_be_onair', True)
        wait_for = kwargs.pop('wait_for', 60)
        timeout = kwargs.pop('timeout', 60)
        alias = kwargs.pop('alias', 'default')

        bts_on_air = True
        if should_be_onair is True:
            bts_on_air = self._verify_bts_status_when_it_shouldbe_on_air(req_rat, timeout,
                                                                         wait_for, alias)
            if bts_on_air is not True:
                raise BtsNotOnAirException
        elif should_be_onair is False:
            bts_on_air = self._verify_bts_status_when_it_should_not_be_on_air(bts_on_air, req_rat,
                                                                              timeout, alias)
            if bts_on_air is not False:
                raise BtsOnAirException
        logger.debug('bts_on_air', bts_on_air)
        return bts_on_air

    def _verify_bts_status_when_it_shouldbe_on_air(self, req_rat, timeout, wait_for, alias):
        logger.debug("Bts should be on air...\nverifying if bts is on air....")
        for iter in range(old_div(int(wait_for), 10)):
            time.sleep(10)
            cell_status_dict = self._get_cell_status_dict(req_rat, timeout, alias)
            if len(cell_status_dict) == 0:
                continue
            else:
                bts_on_air = self._check_if_all_rats_are_on_air(cell_status_dict)
                if bts_on_air is True:
                    return True
                else:
                    continue
        return False

    def _check_if_all_rats_are_on_air(self, cell_status_dict):
        for cell_status in list(cell_status_dict.values()):
            if cell_status != 'onairdone':
                return False
        return True

    def _verify_bts_status_when_it_should_not_be_on_air(self, bts_on_air, req_rat, timeout, alias):
        logger.debug("Bts should not be on air...\nverifying if bts is on air....")
        cell_status_dict = self._get_cell_status_dict(req_rat, timeout, alias)
        if len(cell_status_dict) == 0:
            bts_on_air = False
            return bts_on_air
        else:
            for cell_status in list(cell_status_dict.values()):
                if cell_status != 'onairdone':
                    bts_on_air = False
                    return bts_on_air

    def _get_cell_status_dict(self, req_rat, timeout, alias):
        cell_status_dict = {}
        req_rat = get_config_variable(['rat_env']) if req_rat == 'all' else req_rat
        if not isinstance(req_rat, list):
            req_rat = [req_rat]
        req_rat = [rat.replace('5g', 'nr') for rat in req_rat]
        try:
            all_cells_data = self.factory.admin.get_managed_objects(class_name='CELL_M',
                                                                    timeout=float(timeout),
                                                                    connection=alias)
            for cell_data in all_cells_data:
                cell_rat = cell_data['parameters']['rat'].lower()
                # if cell_rat in get_config_variable(['rat_env']) and cell_rat in req_rat:
                if cell_rat in req_rat:
                    # self._wait_for_onair_status(cell_data, timeout, alias)
                    # Use Wait for on air later
                    self._get_cell_status(cell_data, cell_rat, cell_status_dict)
                else:
                    logger.info('Ignored {} cell'.format(cell_rat))
            logger.debug(cell_status_dict)
        except Exception as err:
            logger.debug('ADMIN API exception: {}'.format(err))
        return cell_status_dict

