    def _get_cell_status_new(self, cell_data, cell_rat, cell_status_dict):
        logger.debug("Getting {} cell status".format(cell_rat))
        cell_status = cell_data['proceduralState']
        if cell_rat not in cell_status_dict or cell_status_dict[cell_rat].lower() != 'onairdone':
            cell_status_dict[cell_rat] = cell_status.lower()

    def _get_cell_status(self, cell_data, cell_rat, cell_status_dict):
        logger.debug("Getting {} cell status".format(cell_rat))
        cell_status = cell_data['parameters']['stateInfo']['proceduralState']
        if cell_rat not in cell_status_dict or cell_status_dict[cell_rat].lower() != 'onairdone':
            cell_status_dict[cell_rat] = cell_status.lower()

    def _wait_for_onair_status(self, cell_data, timeout, alias):
        # After waiting for first cell to be onAir,
        # subsequent cells will need no time to come onAir.
        params = {'stateInfo.proceduralState': 'OnAirDone'}
        cell_distname = cell_data['distName']
        self.factory.admin.wait_for_parameters_value(cell_distname, timeout=timeout, alias=alias,
                                                     **params)

    def block(self, **kwargs):
        target = kwargs['operation'].lower()
        if target == 'site':
            return self._block_site(kwargs)
        elif target == 'cell':
            return self._block_cell(kwargs)
        elif target == 'dist_name':
            return self._block_distname(kwargs)
        else:
            raise Exception('Operation {} not supported'.format(target))

    def _block_site(self, kwargs):
        # site_distname = "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1"
        timeout = kwargs.get("timeout", 60)
        alias = kwargs.get("alias", 'default')
        return self.factory.admin.block(timeout=timeout, connection=alias)

    def unblock(self, **kwargs):
        target = kwargs['operation'].lower()
        if target == 'site':
            return self._unblock_site(kwargs)
        elif target == 'cell':
            return self._unblock_cell(kwargs)
        elif target == 'dist_name':
            return self._unblock_distname(kwargs)
        else:
            raise Exception('Operation {} not supported'.format(target))

    def _unblock_site(self, kwargs):
        # site_distname = "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1"
        timeout = kwargs.get("timeout", 60)
        alias = kwargs.get("alias", 'default')
        wait_for_reconnection = kwargs.get("wait_for_reconnection", True)
        # return self.factory.admin.unblock(site_distname, timeout=timeout, alias=alias)
        return self.factory.admin.unblock(wait_for_reconnection=wait_for_reconnection, timeout=timeout,
                                          connection=alias)

    def _block_distname(self, kwargs):
        dist_name = kwargs.get('dist_name')
        timeout = kwargs.get("timeout", 60)
        alias = kwargs.get("alias", 'default')
        return self.factory.admin.block_cell(dist_name, timeout=timeout, connection=alias)

    def _unblock_distname(self, kwargs):
        dist_name = kwargs.get('dist_name')
        timeout = kwargs.get("timeout", 60)
        alias = kwargs.get("alias", 'default')
        return self.factory.admin.unblock_cell(dist_name, timeout=timeout, connection=alias)

    @check_rat
    def block_cell(self, **kwargs):
        return self._block_cell(kwargs)

    def _block_cell(self, kwargs):
        """ This function blocks all cells under a given parent_rat.
                :param *kwargs: rat The parent RAT, of all the cells that need to be blocked
                :param *kwargs: timeout Time to wait for positive procedure result
                :param *kwargs: alias Name of execution context
            """
        given_rat = kwargs.pop("rat")
        timeout = kwargs.pop("timeout", 300)
        alias = kwargs.pop("alias", 'default')
        # cells_distnames_dict = self.distnames.get_distnames_of_all_configured_cells(alias)
        block_response = self.factory.admin.block_all_cells(given_rat.upper(), timeout, detailed_output=True,
                                                            connection=alias)
        logger.info("Block cell Response is {}".format(block_response))

    @check_rat
    def unblock_cell(self, **kwargs):
        self._unblock_cell(kwargs)

    def _unblock_cell(self, kwargs):
        """ This function unblocks all cells under a given parent_rat.
                :param *kwargs: rat The parent RAT, of all the cells that need to be unblocked
                :param *kwargs: timeout Time to wait for positive procedure result
                :param *kwargs: alias Name of execution context
            """
        given_rat = kwargs.pop("rat")
        timeout = kwargs.pop("timeout", 300)
        alias = kwargs.pop("alias", 'default')
        # cells_distnames_dict = self.distnames.get_distnames_of_all_configured_cells(alias)
        # for cell_rat in cells_distnames_dict:
        #     if cell_rat.lower() == given_rat.lower():
        #         for cell_distname in cells_distnames_dict[cell_rat]:
        #             self.factory.admin.unblock(cell_distname, timeout=timeout, alias=alias)
        unblock_response = self.factory.admin.unblock_all_cells(given_rat.upper(), timeout, detailed_output=True,
                                                                connection=alias)
        logger.info("UnBlock cell Response is {}".format(unblock_response))

