    def lock(self, **kwargs):
        """ This function Locks RMOD or cell or site.
            :param dist_name: Object to lock
            :param timeout: Time to wait for positive procedure result
            :param alias: Name of execution context
        """
        alias, dist_names, timeout = self._get_distnames_for_operation(kwargs)
        for dist_name in dist_names:
            self.factory.admin.lock(dist_name=dist_name, timeout=timeout, connection=alias)

    def unlock(self, **kwargs):
        """ This function unlocks RMOD or cell or site.
                    :param dist_name: Object to unlock
                    :param timeout: Time to wait for positive procedure result
                    :param alias: Name of execution context
        """
        alias, dist_names, timeout = self._get_distnames_for_operation(kwargs)
        for dist_name in dist_names:
            self.factory.admin.unlock(dist_name=dist_name, timeout=timeout, connection=alias)

    def _get_distnames_for_operation(self, kwargs):
        operation = kwargs['operation'].lower()
        timeout = kwargs.pop("timeout", 30)
        alias = kwargs.pop("alias", 'default')
        # dist_name = kwargs["dist_name"]
        dist_names = []
        if operation == 'site':
            parameter_class_obj = Parameters()
            site_distname = parameter_class_obj.get_parameter(param_path="//MRBTS_R-1:dist_name", str_format=True,
                                                              alias=alias)
            dist_names.append(site_distname)
        elif operation == 'cell':
            given_rat = kwargs["rat"]
            if given_rat is not None:
                cells_distnames_dict = self.distnames.get_distnames_of_all_configured_cells(alias, timeout)
                for cell_rat in cells_distnames_dict:
                    if cell_rat.lower() == given_rat.lower():
                        for cell_distname in cells_distnames_dict[cell_rat]:
                            dist_names.append(cell_distname)
        return alias, dist_names, timeout
